-- Platform Intelligence schema tests. Run AFTER 001_pi_schema.up.sql on the disposable test database.
-- Identities: u(1)=owner, u(2)=user1, u(3)=user2, u(4)=user3. Every result is recorded in pgtest.results.

-- ===================================================================== A. structure + safe defaults
SELECT pgtest.q('A1 sixteen pi_ tables exist', $$(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'pi\_%' AND relkind='r') = 16$$);
SELECT pgtest.q('A2 RLS enabled on every pi_ table', $$(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'pi\_%' AND relkind='r' AND relrowsecurity) = 16$$);
SELECT pgtest.q('A3 all 8 feature flags exist and ALL are disabled', $$(SELECT count(*) = 8 AND bool_and(NOT enabled) FROM public.pi_feature_flags)$$);
SELECT pgtest.q('A4 all 10 policy categories exist, all disabled, no automatic action allowed', $$(SELECT count(*) = 10 AND bool_and(NOT enabled) AND bool_and(max_auto_action='none') FROM public.pi_policies)$$);
SELECT pgtest.q('A5 serious categories default to mandatory human review', $$(SELECT bool_and(always_human_review) FROM public.pi_policies WHERE category IN ('threats_violence','sexual_exploitation','repeated_violations'))$$);
SELECT pgtest.q('A6 schema version 1 recorded', $$(SELECT count(*)=1 FROM public.pi_schema_version WHERE version=1)$$);
SELECT pgtest.q('A7 no activity rows were seeded (no fake data)', $$(SELECT (SELECT count(*) FROM public.pi_moderation_cases)+(SELECT count(*) FROM public.pi_content_analyses)+(SELECT count(*) FROM public.pi_moderation_actions)+(SELECT count(*) FROM public.pi_security_events)+(SELECT count(*) FROM public.pi_account_risk_assessments)+(SELECT count(*) FROM public.pi_jobs)+(SELECT count(*) FROM public.pi_audit_log)+(SELECT count(*) FROM public.pi_ai_provider_usage) = 0)$$);
SELECT pgtest.q('A8 every pi_ function pins search_path', $$NOT EXISTS (SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'pi\_%' AND (proconfig IS NULL OR proconfig::text NOT LIKE '%search_path%'))$$);

-- ===================================================================== B. privileges
SELECT pgtest.q('B1 anon has no privilege at all on any pi_ table', $$NOT EXISTS (SELECT 1 FROM pg_tables t, unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE']) p WHERE t.schemaname='public' AND t.tablename LIKE 'pi\_%' AND has_table_privilege('anon', format('public.%I', t.tablename), p))$$);
SELECT pgtest.q('B2 authenticated has SELECT only (no writes) on pi_ tables', $$NOT EXISTS (SELECT 1 FROM pg_tables t, unnest(ARRAY['INSERT','UPDATE','DELETE','TRUNCATE']) p WHERE t.schemaname='public' AND t.tablename LIKE 'pi\_%' AND has_table_privilege('authenticated', format('public.%I', t.tablename), p))$$);
SELECT pgtest.q('B3 only service_role may run queue / audit / decision functions', $$NOT has_function_privilege('anon','public.pi_claim_jobs(text,integer,interval,text[])','EXECUTE') AND NOT has_function_privilege('authenticated','public.pi_claim_jobs(text,integer,interval,text[])','EXECUTE') AND NOT has_function_privilege('authenticated','public.pi_write_audit(uuid,text,text,text,text,jsonb,jsonb,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.pi_decide_appeal(uuid,uuid,text,text)','EXECUTE') AND has_function_privilege('service_role','public.pi_decide_appeal(uuid,uuid,text,text)','EXECUTE')$$);
SELECT pgtest.q('B4 users can call exactly the two user-facing functions; anon cannot', $$has_function_privilege('authenticated','public.pi_submit_appeal(uuid,text)','EXECUTE') AND has_function_privilege('authenticated','public.pi_my_moderation_notices()','EXECUTE') AND NOT has_function_privilege('anon','public.pi_submit_appeal(uuid,text)','EXECUTE') AND NOT has_function_privilege('anon','public.pi_my_moderation_notices()','EXECUTE')$$);

-- ===================================================================== C. policies (admin-editable config)
SELECT pgtest.t('C1 cannot enable a policy without a review threshold', $$UPDATE public.pi_policies SET enabled=true WHERE category='spam_scams'$$, 'service_role', NULL, '23514');
SELECT pgtest.t('C2 cannot allow an automatic action without an auto-action threshold', $$UPDATE public.pi_policies SET max_auto_action='warn' WHERE category='spam_scams'$$, 'service_role', NULL, '23514');
SELECT pgtest.t('C3 auto-action threshold cannot be below review threshold', $$UPDATE public.pi_policies SET review_threshold=0.9, auto_action_threshold=0.5, max_auto_action='warn' WHERE category='spam_scams'$$, 'service_role', NULL, '23514');
SELECT pgtest.t('C4 automation can never be allowed to ban (value rejected)', $$UPDATE public.pi_policies SET review_threshold=0.5, auto_action_threshold=0.9, max_auto_action='ban' WHERE category='spam_scams'$$, 'service_role', NULL, '23514');
SELECT pgtest.t('C5 automation can never be allowed to suspend (value rejected)', $$UPDATE public.pi_policies SET review_threshold=0.5, auto_action_threshold=0.9, max_auto_action='suspend' WHERE category='spam_scams'$$, 'service_role', NULL, '23514');
SELECT pgtest.t('C6 thresholds outside 0..1 are rejected', $$UPDATE public.pi_policies SET review_threshold=1.5 WHERE category='spam_scams'$$, 'service_role', NULL, '23514');
SELECT pgtest.t('C7 a valid policy update succeeds', $$UPDATE public.pi_policies SET review_threshold=0.700, auto_action_threshold=0.900, max_auto_action='warn', enabled=true WHERE category='spam_scams'$$, 'service_role');
SELECT pgtest.q('C8 a behavioural change bumps the policy version', $$(SELECT version=2 FROM public.pi_policies WHERE category='spam_scams')$$);
SELECT pgtest.t('C9 a description-only change does not bump the version', $$UPDATE public.pi_policies SET description='Spam and scams (edited)' WHERE category='spam_scams'$$, 'service_role');
SELECT pgtest.q('C10 version unchanged after description-only edit', $$(SELECT version=2 FROM public.pi_policies WHERE category='spam_scams')$$);
SELECT pgtest.t('C11 unknown category rejected by the domain', $$INSERT INTO public.pi_policies (category, description) VALUES ('made_up_category','x')$$, 'service_role', NULL, '23514');
SELECT pgtest.t('C12 feature-flag keys must be lower_snake_case', $$INSERT INTO public.pi_feature_flags (key, description) VALUES ('Bad Key!','x')$$, 'service_role', NULL, '23514');

-- ===================================================================== D. cases + analyses (idempotency, no invented results)
SELECT pgtest.t('D1 create a moderation case', format($$INSERT INTO public.pi_moderation_cases (id, subject_type, subject_id, subject_user_id, source, status, idempotency_key, requires_human_review) VALUES (%L,'post',%L,%L,'automated','awaiting_review','case:post:a0001',true)$$, pgtest.u(101), '00000000-0000-0000-0000-0000000a0001', pgtest.u(2)), 'service_role');
SELECT pgtest.t('D2 duplicate idempotency key rejected', format($$INSERT INTO public.pi_moderation_cases (subject_type, subject_id, source, idempotency_key) VALUES ('post',%L,'automated','case:post:a0001')$$, pgtest.u(999)), 'service_role', NULL, '23505');
SELECT pgtest.t('D3 invalid case status rejected', format($$INSERT INTO public.pi_moderation_cases (subject_type, subject_id, source, status) VALUES ('post',%L,'automated','banana')$$, pgtest.u(999)), 'service_role', NULL, '23514');
SELECT pgtest.t('D4 resolved case must carry resolved_at', format($$INSERT INTO public.pi_moderation_cases (subject_type, subject_id, source, status) VALUES ('post',%L,'automated','resolved')$$, pgtest.u(999)), 'service_role', NULL, '23514');
SELECT pgtest.t('D5 risk score above 1 rejected', format($$INSERT INTO public.pi_moderation_cases (subject_type, subject_id, source, risk_score) VALUES ('post',%L,'automated',1.5)$$, pgtest.u(999)), 'service_role', NULL, '23514');
SELECT pgtest.t('D6 valid analysis stored (hash only, no raw text)', format($$INSERT INTO public.pi_content_analyses (case_id, subject_type, subject_id, subject_user_id, analysis_kind, content_hash, content_length, provider, outcome, risk_score, confidence, top_category, category_scores) VALUES (%L,'post',%L,%L,'text',repeat('a',64),120,'bmn_rules','uncertain',0.55,0.4,'spam_scams','{"spam_scams":0.55}')$$, pgtest.u(101), '00000000-0000-0000-0000-0000000a0001', pgtest.u(2)), 'service_role');
SELECT pgtest.t('D7 content hash must be 64-char hex (raw text cannot be stored there)', format($$INSERT INTO public.pi_content_analyses (subject_type, subject_id, analysis_kind, content_hash, provider, outcome, risk_score) VALUES ('post',%L,'text','hello world','bmn_rules','clear',0.1)$$, pgtest.u(999)), 'service_role', NULL, '23514');
SELECT pgtest.t('D8 a "clear" result without a score is rejected (no invented results)', format($$INSERT INTO public.pi_content_analyses (subject_type, subject_id, analysis_kind, content_hash, provider, outcome) VALUES ('post',%L,'text',repeat('b',64),'bmn_rules','clear')$$, pgtest.u(999)), 'service_role', NULL, '23514');
SELECT pgtest.t('D9 a provider_error must record the error', format($$INSERT INTO public.pi_content_analyses (subject_type, subject_id, analysis_kind, content_hash, provider, outcome) VALUES ('post',%L,'text',repeat('c',64),'some_provider','provider_error')$$, pgtest.u(999)), 'service_role', NULL, '23514');
SELECT pgtest.t('D10 a provider_error with its error and no score is accepted', format($$INSERT INTO public.pi_content_analyses (subject_type, subject_id, analysis_kind, content_hash, provider, outcome, error) VALUES ('post',%L,'text',repeat('c',64),'some_provider','provider_error','timeout')$$, pgtest.u(999)), 'service_role');
SELECT pgtest.t('D11 a skipped analysis needs no score', format($$INSERT INTO public.pi_content_analyses (subject_type, subject_id, analysis_kind, content_hash, provider, outcome) VALUES ('post',%L,'text',repeat('d',64),'bmn_rules','skipped')$$, pgtest.u(999)), 'service_role');

-- ===================================================================== E. actions: automation limits + immutability
SELECT pgtest.t('E1 SYSTEM cannot ban', format($$INSERT INTO public.pi_moderation_actions (case_id, target_user_id, subject_type, subject_id, action_type, actor_type, mode, user_visible_reason) VALUES (%L,%L,'account',%L,'ban','system','enforced','x')$$, pgtest.u(101), pgtest.u(2), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('E2 SYSTEM cannot suspend', format($$INSERT INTO public.pi_moderation_actions (case_id, target_user_id, subject_type, subject_id, action_type, actor_type, mode, user_visible_reason) VALUES (%L,%L,'account',%L,'suspend','system','enforced','x')$$, pgtest.u(101), pgtest.u(2), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('E3 SYSTEM cannot remove content', format($$INSERT INTO public.pi_moderation_actions (case_id, target_user_id, subject_type, subject_id, action_type, actor_type, mode, user_visible_reason) VALUES (%L,%L,'post',%L,'remove_content','system','enforced','x')$$, pgtest.u(101), pgtest.u(2), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('E4 SYSTEM cannot revoke verification', format($$INSERT INTO public.pi_moderation_actions (case_id, target_user_id, subject_type, subject_id, action_type, actor_type, mode, user_visible_reason) VALUES (%L,%L,'account',%L,'revoke_verification','system','enforced','x')$$, pgtest.u(101), pgtest.u(2), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('E5 SYSTEM hold without an expiry is rejected', format($$INSERT INTO public.pi_moderation_actions (case_id, target_user_id, subject_type, subject_id, action_type, actor_type, mode) VALUES (%L,%L,'post',%L,'hide_pending_review','system','enforced')$$, pgtest.u(101), pgtest.u(2), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('E6 owner ban without a user-visible reason is rejected', format($$INSERT INTO public.pi_moderation_actions (case_id, target_user_id, subject_type, subject_id, action_type, actor_type, actor_id, mode) VALUES (%L,%L,'account',%L,'ban','owner',%L,'enforced')$$, pgtest.u(101), pgtest.u(2), pgtest.u(2), pgtest.u(1)), 'service_role', NULL, '23514');
SELECT pgtest.t('E7 SYSTEM shadow-mode flag recorded (A1: not applied)', format($$INSERT INTO public.pi_moderation_actions (id, case_id, target_user_id, subject_type, subject_id, action_type, actor_type, mode, idempotency_key) VALUES (%L,%L,%L,'post',%L,'flag','system','shadow','act:1')$$, pgtest.u(201), pgtest.u(101), pgtest.u(2), pgtest.u(2)), 'service_role');
SELECT pgtest.t('E8 owner enforced warning (A2)', format($$INSERT INTO public.pi_moderation_actions (id, case_id, target_user_id, subject_type, subject_id, action_type, actor_type, actor_id, mode, reason_code, user_visible_reason, internal_note, confidence) VALUES (%L,%L,%L,'post',%L,'warn','owner',%L,'enforced','spam_scams','Your post looked like spam.','internal: score .55',0.55)$$, pgtest.u(202), pgtest.u(101), pgtest.u(2), pgtest.u(2), pgtest.u(1)), 'service_role');
SELECT pgtest.t('E9 owner enforced content removal with reason (A3)', format($$INSERT INTO public.pi_moderation_actions (id, case_id, target_user_id, subject_type, subject_id, action_type, actor_type, actor_id, mode, reason_code, user_visible_reason) VALUES (%L,%L,%L,'post',%L,'remove_content','owner',%L,'enforced','hate_speech','Removed: hate speech.')$$, pgtest.u(203), pgtest.u(101), pgtest.u(2), pgtest.u(2), pgtest.u(1)), 'service_role');
SELECT pgtest.t('E10 shadow warning (A4: must stay invisible to the user)', format($$INSERT INTO public.pi_moderation_actions (id, case_id, target_user_id, subject_type, subject_id, action_type, actor_type, mode) VALUES (%L,%L,%L,'post',%L,'warn','system','shadow')$$, pgtest.u(204), pgtest.u(101), pgtest.u(2), pgtest.u(2)), 'service_role');
SELECT pgtest.t('E11 SYSTEM temporary hold WITH expiry is accepted', format($$INSERT INTO public.pi_moderation_actions (id, case_id, target_user_id, subject_type, subject_id, action_type, actor_type, mode, expires_at) VALUES (%L,%L,%L,'post',%L,'hide_pending_review','system','shadow', now()+interval '1 day')$$, pgtest.u(205), pgtest.u(101), pgtest.u(2), pgtest.u(2)), 'service_role');
SELECT pgtest.t('E12 action history cannot be edited (action_type)', format($$UPDATE public.pi_moderation_actions SET action_type='no_action' WHERE id=%L$$, pgtest.u(203)), 'service_role', NULL, '42501');
SELECT pgtest.t('E13 action history cannot be edited (internal note)', format($$UPDATE public.pi_moderation_actions SET internal_note='rewritten' WHERE id=%L$$, pgtest.u(202)), 'service_role', NULL, '42501');
SELECT pgtest.t('E14 action history cannot be edited (mode shadow->enforced)', format($$UPDATE public.pi_moderation_actions SET mode='enforced' WHERE id=%L$$, pgtest.u(204)), 'service_role', NULL, '42501');
SELECT pgtest.t('E15 action history cannot be deleted', format($$DELETE FROM public.pi_moderation_actions WHERE id=%L$$, pgtest.u(203)), 'service_role', NULL, '42501');
SELECT pgtest.t('E16 reversal fields CAN be written once (A3 reversed by owner)', format($$UPDATE public.pi_moderation_actions SET reversed_at=now(), reversed_by=%L, reversal_reason='mistake' WHERE id=%L$$, pgtest.u(1), pgtest.u(203)), 'service_role');
SELECT pgtest.t('E17 a reversal cannot be rewritten', format($$UPDATE public.pi_moderation_actions SET reversal_reason='changed my mind' WHERE id=%L$$, pgtest.u(203)), 'service_role', NULL, '42501');
SELECT pgtest.t('E18 reversal reason without reversal timestamp rejected', format($$UPDATE public.pi_moderation_actions SET reversal_reason='x' WHERE id=%L$$, pgtest.u(202)), 'service_role', NULL, '23514');

-- ===================================================================== F. user-facing notices + appeals
SELECT pgtest.q('F1 notices expose only enforced actions (shadow + flag hidden): user1 sees A2 and A3', $$(SELECT count(*)=2 FROM public.pi_my_moderation_notices())$$, 'authenticated', pgtest.u(2));
SELECT pgtest.q('F2 notices never include internal columns', $$NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname='pi_my_moderation_notices' AND pg_get_function_result(oid) ~ 'internal_note|confidence|policy|actor|score|analysis')$$);
SELECT pgtest.q('F3 another user sees none of user1''s notices', $$(SELECT count(*)=0 FROM public.pi_my_moderation_notices())$$, 'authenticated', pgtest.u(3));
SELECT pgtest.q('F4 reversed action is listed as reversed and no longer appealable', format($$(SELECT reversed AND NOT appealable FROM public.pi_my_moderation_notices() WHERE action_id=%L)$$, pgtest.u(203)), 'authenticated', pgtest.u(2));
SELECT pgtest.t('F5 anonymous user cannot appeal (no execute right)', format($$SELECT public.pi_submit_appeal(%L, 'I think this was a mistake.')$$, pgtest.u(202)), 'anon', NULL, '42501');
SELECT pgtest.t('F6 user cannot appeal someone else''s action', format($$SELECT public.pi_submit_appeal(%L, 'I think this was a mistake.')$$, pgtest.u(202)), 'authenticated', pgtest.u(3), 'P0002');
SELECT pgtest.t('F7 cannot appeal a shadow (never-applied) decision', format($$SELECT public.pi_submit_appeal(%L, 'I think this was a mistake.')$$, pgtest.u(204)), 'authenticated', pgtest.u(2), 'P0001');
SELECT pgtest.t('F8 cannot appeal an already-reversed action', format($$SELECT public.pi_submit_appeal(%L, 'I think this was a mistake.')$$, pgtest.u(203)), 'authenticated', pgtest.u(2), 'P0001');
SELECT pgtest.t('F9 appeal statement must be at least 10 characters', format($$SELECT public.pi_submit_appeal(%L, 'short')$$, pgtest.u(202)), 'authenticated', pgtest.u(2), '23514');
SELECT pgtest.t('F10 owner of the action can appeal an enforced warning', format($$SELECT public.pi_submit_appeal(%L, 'This post was not spam, it was my own music.')$$, pgtest.u(202)), 'authenticated', pgtest.u(2));
SELECT pgtest.t('F11 only one appeal per action', format($$SELECT public.pi_submit_appeal(%L, 'Appealing again with more words.')$$, pgtest.u(202)), 'authenticated', pgtest.u(2), '23505');
SELECT pgtest.q('F12 user sees their own appeal; other users and anon do not', $$(SELECT count(*)=1 FROM public.pi_appeals)$$, 'authenticated', pgtest.u(2));
SELECT pgtest.q('F13 another user sees zero appeals', $$(SELECT count(*)=0 FROM public.pi_appeals)$$, 'authenticated', pgtest.u(3));
SELECT pgtest.q('F14 appeal submission was written to the audit log', $$(SELECT count(*)=1 FROM public.pi_audit_log WHERE action='appeal_submitted')$$);
SELECT pgtest.t('F15 users cannot decide appeals (no execute right)', format($$SELECT public.pi_decide_appeal(%L, (SELECT id FROM public.pi_appeals LIMIT 1), 'overturned', 'let me off')$$, pgtest.u(2)), 'authenticated', pgtest.u(2), '42501');
SELECT pgtest.t('F16 service role acting as a NON-owner is refused by the database itself', format($$SELECT public.pi_decide_appeal(%L, (SELECT id FROM public.pi_appeals LIMIT 1), 'overturned', 'let me off')$$, pgtest.u(2)), 'service_role', NULL, '42501');
SELECT pgtest.t('F17 a decision requires a note', format($$SELECT public.pi_decide_appeal(%L, (SELECT id FROM public.pi_appeals LIMIT 1), 'overturned', '  ')$$, pgtest.u(1)), 'service_role', NULL, '22023');
SELECT pgtest.t('F18 a decision must be upheld or overturned', format($$SELECT public.pi_decide_appeal(%L, (SELECT id FROM public.pi_appeals LIMIT 1), 'banana', 'note')$$, pgtest.u(1)), 'service_role', NULL, '22023');
SELECT pgtest.t('F19 owner overturns the appeal', format($$SELECT public.pi_decide_appeal(%L, (SELECT id FROM public.pi_appeals LIMIT 1), 'overturned', 'Reviewed the post; not spam.')$$, pgtest.u(1)), 'service_role');
SELECT pgtest.q('F20 overturning reversed the action', format($$(SELECT reversed_at IS NOT NULL AND reversed_by=%L FROM public.pi_moderation_actions WHERE id=%L)$$, pgtest.u(1), pgtest.u(202)));
SELECT pgtest.q('F21 overturning queued exactly one idempotent reverse_action job', format($$(SELECT count(*)=1 FROM public.pi_jobs WHERE job_type='reverse_action' AND idempotency_key='reverse_action:'||%L)$$, pgtest.u(202)::text));
SELECT pgtest.q('F22 the decision was audited with the owner as actor', format($$(SELECT count(*)=1 FROM public.pi_audit_log WHERE action='appeal_overturned' AND actor_id=%L AND actor_type='owner')$$, pgtest.u(1)));
SELECT pgtest.t('F23 an appeal cannot be decided twice', format($$SELECT public.pi_decide_appeal(%L, (SELECT id FROM public.pi_appeals LIMIT 1), 'upheld', 'second thoughts')$$, pgtest.u(1)), 'service_role', NULL, 'P0001');
SELECT pgtest.q('F24 repeat-offender count ignores reversed actions (both of user1''s enforced actions are reversed)', format($$public.pi_violation_count(%L)=0$$, pgtest.u(2)), 'service_role');
SELECT pgtest.t('F25 a new enforced, un-reversed warning is recorded', format($$INSERT INTO public.pi_moderation_actions (case_id, target_user_id, subject_type, subject_id, action_type, actor_type, actor_id, mode, user_visible_reason) VALUES (%L,%L,'post',%L,'warn','owner',%L,'enforced','Second warning')$$, pgtest.u(101), pgtest.u(2), pgtest.u(2), pgtest.u(1)), 'service_role');
SELECT pgtest.q('F26 repeat-offender count now sees exactly that one action', format($$public.pi_violation_count(%L)=1$$, pgtest.u(2)), 'service_role');
SELECT pgtest.q('F27 a zero-length window counts nothing', format($$public.pi_violation_count(%L, interval '0 seconds')=0$$, pgtest.u(2)), 'service_role');
SELECT pgtest.q('F28 shadow-mode actions never count toward repeat-offender status', format($$(SELECT count(*) FROM public.pi_moderation_actions WHERE target_user_id=%L AND mode='shadow') >= 3 AND public.pi_violation_count(%L)=1$$, pgtest.u(2), pgtest.u(2)), 'service_role');

-- ===================================================================== G. audit log is append-only
SELECT pgtest.t('G1 audit rows cannot be updated', $$UPDATE public.pi_audit_log SET reason='tampered'$$, 'service_role', NULL, '42501');
SELECT pgtest.t('G2 audit rows cannot be deleted', $$DELETE FROM public.pi_audit_log$$, 'service_role', NULL, '42501');
SELECT pgtest.t('G3 audit log cannot be truncated', $$TRUNCATE public.pi_audit_log$$, 'service_role', NULL, '42501');
SELECT pgtest.t('G4 audit append works through pi_write_audit', format($$SELECT public.pi_write_audit(%L,'owner','policy_changed','policy','spam_scams','{"enabled":false}','{"enabled":true}','test')$$, pgtest.u(1)), 'service_role');
SELECT pgtest.t('G5 raw (non-hash) IP address is rejected in audit log', $$INSERT INTO public.pi_audit_log (actor_type, action, ip_hash) VALUES ('system','x','203.0.113.7')$$, 'service_role', NULL, '23514');

-- ===================================================================== H. account risk + security events + restrictions
SELECT pgtest.t('H1 risk above "low" must carry reason codes (explainability)', format($$INSERT INTO public.pi_account_risk_assessments (user_id, risk_score, risk_level, explanation, model_version) VALUES (%L,0.8,'high','x','rules-1')$$, pgtest.u(3)), 'service_role', NULL, '23514');
SELECT pgtest.t('H2 explained high risk accepted', format($$INSERT INTO public.pi_account_risk_assessments (user_id, risk_score, risk_level, reason_codes, signals, explanation, model_version) VALUES (%L,0.8,'high','{mass_follow}','[{"signal":"follows_per_hour","value":300}]','300 follows in one hour','rules-1')$$, pgtest.u(3)), 'service_role');
SELECT pgtest.t('H3 only one CURRENT assessment per user', format($$INSERT INTO public.pi_account_risk_assessments (user_id, risk_score, risk_level, explanation, model_version) VALUES (%L,0.1,'low','fine','rules-1')$$, pgtest.u(3)), 'service_role', NULL, '23505');
SELECT pgtest.t('H4 history kept: old assessment retired then new one accepted', format($$WITH r AS (UPDATE public.pi_account_risk_assessments SET is_current=false WHERE user_id=%L RETURNING 1) INSERT INTO public.pi_account_risk_assessments (user_id, risk_score, risk_level, explanation, model_version) SELECT %L,0.1,'low','recovered','rules-1' FROM r$$, pgtest.u(3), pgtest.u(3)), 'service_role');
SELECT pgtest.q('H5 ordinary user cannot read risk assessments (private security signals)', $$(SELECT count(*)=0 FROM public.pi_account_risk_assessments)$$, 'authenticated', pgtest.u(3));
SELECT pgtest.t('H6 invalid risk level rejected', format($$INSERT INTO public.pi_account_risk_assessments (user_id, risk_score, risk_level, explanation, model_version, is_current) VALUES (%L,0.1,'extreme','x','m',false)$$, pgtest.u(3)), 'service_role', NULL, '23514');
SELECT pgtest.t('H7 security event stores a hashed IP', format($$INSERT INTO public.pi_security_events (user_id, event_type, severity, source, ip_hash, dedupe_key) VALUES (%L,'mass_follow','high','follow_monitor',repeat('f',64),'evt:1')$$, pgtest.u(3)), 'service_role');
SELECT pgtest.t('H8 security event with a raw IP is rejected', format($$INSERT INTO public.pi_security_events (user_id, event_type, severity, source, ip_hash) VALUES (%L,'mass_follow','high','follow_monitor','198.51.100.4')$$, pgtest.u(3)), 'service_role', NULL, '23514');
SELECT pgtest.t('H9 duplicate security event (same dedupe key) rejected', format($$INSERT INTO public.pi_security_events (user_id, event_type, severity, source, dedupe_key) VALUES (%L,'mass_follow','high','follow_monitor','evt:1')$$, pgtest.u(3)), 'service_role', NULL, '23505');
SELECT pgtest.t('H10 unknown event type rejected', format($$INSERT INTO public.pi_security_events (user_id, event_type, severity, source) VALUES (%L,'telepathy','low','x')$$, pgtest.u(3)), 'service_role', NULL, '23514');
SELECT pgtest.q('H11 ordinary user cannot read security events', $$(SELECT count(*)=0 FROM public.pi_security_events)$$, 'authenticated', pgtest.u(3));
SELECT pgtest.t('H12 protective restriction must be temporary and forward-dated', format($$INSERT INTO public.pi_protective_restrictions (user_id, restriction_type, reason_code, actor_type, starts_at, expires_at) VALUES (%L,'limit_follows','mass_follow','system', now(), now() - interval '1 hour')$$, pgtest.u(3)), 'service_role', NULL, '23514');
SELECT pgtest.t('H13 temporary restriction accepted (shadow by default)', format($$INSERT INTO public.pi_protective_restrictions (user_id, restriction_type, reason_code, actor_type, expires_at) VALUES (%L,'limit_follows','mass_follow','system', now() + interval '6 hours')$$, pgtest.u(3)), 'service_role');
SELECT pgtest.q('H14 restrictions default to shadow mode', $$(SELECT mode='shadow' FROM public.pi_protective_restrictions LIMIT 1)$$);
SELECT pgtest.t('H15 permanent-style restriction (no expiry) impossible', format($$INSERT INTO public.pi_protective_restrictions (user_id, restriction_type, reason_code, actor_type) VALUES (%L,'limit_follows','x','system')$$, pgtest.u(3)), 'service_role', NULL, '23502');

-- ===================================================================== I. verification
SELECT pgtest.t('I1 evaluation with every check passing may be "eligible_for_auto_approval"', format($$INSERT INTO public.pi_verification_evaluations (id, verification_request_id, user_id, criteria_version, checks, outcome) VALUES (%L,%L,%L,1,'[{"check":"account_age","result":"pass","source":"profiles.created_at"},{"check":"no_open_violations","result":"pass","source":"pi_moderation_actions"}]','eligible_for_auto_approval')$$, pgtest.u(401), pgtest.u(501), pgtest.u(2)), 'service_role');
SELECT pgtest.t('I2 one unverifiable check blocks auto-approval eligibility', format($$INSERT INTO public.pi_verification_evaluations (verification_request_id, user_id, criteria_version, checks, outcome) VALUES (%L,%L,1,'[{"check":"a","result":"pass"},{"check":"external_identity","result":"unverifiable"}]','eligible_for_auto_approval')$$, pgtest.u(502), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('I3 one failed check blocks auto-approval eligibility', format($$INSERT INTO public.pi_verification_evaluations (verification_request_id, user_id, criteria_version, checks, outcome) VALUES (%L,%L,1,'[{"check":"a","result":"fail"}]','eligible_for_auto_approval')$$, pgtest.u(502), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('I4 an EMPTY check list cannot make an account eligible', format($$INSERT INTO public.pi_verification_evaluations (verification_request_id, user_id, criteria_version, checks, outcome) VALUES (%L,%L,1,'[]','eligible_for_auto_approval')$$, pgtest.u(502), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('I5 checks must be a JSON array', format($$INSERT INTO public.pi_verification_evaluations (verification_request_id, user_id, criteria_version, checks, outcome) VALUES (%L,%L,1,'{"a":"pass"}','needs_human_review')$$, pgtest.u(502), pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('I6 uncertain case is recorded as needing human review', format($$INSERT INTO public.pi_verification_evaluations (id, verification_request_id, user_id, criteria_version, checks, outcome) VALUES (%L,%L,%L,1,'[{"check":"external_identity","result":"unverifiable"}]','needs_human_review')$$, pgtest.u(402), pgtest.u(502), pgtest.u(2)), 'service_role');
SELECT pgtest.t('I7 SYSTEM cannot reject a verification', format($$INSERT INTO public.pi_verification_decisions (user_id, decision, decided_by_type, reason) VALUES (%L,'rejected','system','auto')$$, pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('I8 SYSTEM cannot revoke a verification', format($$INSERT INTO public.pi_verification_decisions (user_id, decision, decided_by_type, reason) VALUES (%L,'revoked','system','auto')$$, pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('I9 SYSTEM approval without an evaluation is rejected', format($$INSERT INTO public.pi_verification_decisions (user_id, decision, decided_by_type, reason) VALUES (%L,'approved','system','auto')$$, pgtest.u(2)), 'service_role', NULL, '23514');
SELECT pgtest.t('I10 SYSTEM approval backed by an evaluation is accepted', format($$INSERT INTO public.pi_verification_decisions (user_id, evaluation_id, decision, decided_by_type, reason) VALUES (%L,%L,'approved','system','all checks passed')$$, pgtest.u(2), pgtest.u(401)), 'service_role');
SELECT pgtest.t('I11 SYSTEM may refer an uncertain case to a human', format($$INSERT INTO public.pi_verification_decisions (user_id, evaluation_id, decision, decided_by_type, reason) VALUES (%L,%L,'referred_to_human','system','external identity unverifiable')$$, pgtest.u(2), pgtest.u(402)), 'service_role');
SELECT pgtest.t('I12 owner can revoke for fraud and flag it', format($$INSERT INTO public.pi_verification_decisions (user_id, decision, decided_by_type, decided_by, reason, fraud_related) VALUES (%L,'revoked','owner',%L,'evidence was fabricated',true)$$, pgtest.u(2), pgtest.u(1)), 'service_role');
SELECT pgtest.t('I13 fraud flag only valid on a revocation', format($$INSERT INTO public.pi_verification_decisions (user_id, decision, decided_by_type, decided_by, reason, fraud_related, evaluation_id) VALUES (%L,'approved','owner',%L,'ok',true,%L)$$, pgtest.u(2), pgtest.u(1), pgtest.u(401)), 'service_role', NULL, '23514');
SELECT pgtest.q('I14 ordinary user cannot read verification evaluations', $$(SELECT count(*)=0 FROM public.pi_verification_evaluations)$$, 'authenticated', pgtest.u(2));

-- ===================================================================== J. AI usage + provider health
SELECT pgtest.t('J1 usage with unknown cost accepted (cost left NULL, never guessed)', $$INSERT INTO public.pi_ai_provider_usage (provider, operation, status) VALUES ('openai','text_moderation','ok')$$, 'service_role');
SELECT pgtest.t('J2 a cost cannot be recorded with basis "unknown"', $$INSERT INTO public.pi_ai_provider_usage (provider, operation, status, cost_usd) VALUES ('openai','text_moderation','ok',0.01)$$, 'service_role', NULL, '23514');
SELECT pgtest.t('J3 basis "reported" requires an actual cost', $$INSERT INTO public.pi_ai_provider_usage (provider, operation, status, cost_basis) VALUES ('anthropic','classification','ok','reported')$$, 'service_role', NULL, '23514');
SELECT pgtest.t('J4 reported cost accepted', $$INSERT INTO public.pi_ai_provider_usage (provider, operation, status, cost_basis, cost_usd, input_tokens, output_tokens) VALUES ('anthropic','classification','ok','reported',0.00042,350,50)$$, 'service_role');
SELECT pgtest.t('J5 negative cost rejected', $$INSERT INTO public.pi_ai_provider_usage (provider, operation, status, cost_basis, cost_usd) VALUES ('x','other','ok','estimated',-1)$$, 'service_role', NULL, '23514');
SELECT pgtest.t('J6 provider health row (degraded mode support)', $$INSERT INTO public.pi_provider_health (provider, state, consecutive_failures, circuit_open_until) VALUES ('openai','down',5, now()+interval '5 minutes')$$, 'service_role');
SELECT pgtest.t('J7 invalid provider state rejected', $$INSERT INTO public.pi_provider_health (provider, state) VALUES ('x','on fire')$$, 'service_role', NULL, '23514');
SELECT pgtest.q('J8 ordinary users cannot read AI usage / cost', $$(SELECT count(*)=0 FROM public.pi_ai_provider_usage)$$, 'authenticated', pgtest.u(2));

-- ===================================================================== K. job queue
SELECT pgtest.t('K1 enqueue jobs (priority 1, 5 w/ 2 attempts, future)', $$INSERT INTO public.pi_jobs (job_type, priority, idempotency_key, max_attempts, run_after) VALUES ('provider_healthcheck',1,'q:hi',3,now()),('provider_healthcheck',5,'q:lo',2,now()),('provider_healthcheck',5,'q:future',3,now()+interval '1 hour')$$, 'service_role');
SELECT pgtest.t('K2 duplicate idempotency key cannot double-enqueue', $$INSERT INTO public.pi_jobs (job_type, idempotency_key) VALUES ('provider_healthcheck','q:hi')$$, 'service_role', NULL, '23505');
SELECT pgtest.t('K3 unknown job type rejected', $$INSERT INTO public.pi_jobs (job_type) VALUES ('mine_bitcoin')$$, 'service_role', NULL, '23514');
SELECT pgtest.t('K4 claim limit of 0 rejected', $$SELECT * FROM public.pi_claim_jobs('w',0)$$, 'service_role', NULL, '22023');
SELECT pgtest.t('K5 blank worker id rejected', $$SELECT * FROM public.pi_claim_jobs(' ',5)$$, 'service_role', NULL, '22023');
SELECT pgtest.q('K6 highest priority is claimed first', $$(SELECT string_agg(idempotency_key,',') FROM public.pi_claim_jobs('wA',1,interval '5 minutes',ARRAY['provider_healthcheck'])) = 'q:hi'$$, 'service_role');
SELECT pgtest.q('K7 a second worker gets the remaining ready job only (no double-claim, future job untouched)', $$(SELECT string_agg(idempotency_key,',') FROM public.pi_claim_jobs('wB',10,interval '5 minutes',ARRAY['provider_healthcheck'])) = 'q:lo'$$, 'service_role');
SELECT pgtest.q('K8 type filter respected: an unrelated type is not claimed', $$(SELECT count(*)=0 FROM public.pi_claim_jobs('wB',10,interval '5 minutes',ARRAY['purge_retention']))$$, 'service_role');
SELECT pgtest.q('K9 completing with the WRONG worker is refused', $$public.pi_complete_job((SELECT id FROM public.pi_jobs WHERE idempotency_key='q:hi'),'wB') = false$$, 'service_role');
SELECT pgtest.q('K10 completing with the right worker succeeds', $$public.pi_complete_job((SELECT id FROM public.pi_jobs WHERE idempotency_key='q:hi'),'wA') = true$$, 'service_role');
SELECT pgtest.q('K11a failing a job with attempts left returns "queued"', $$public.pi_fail_job((SELECT id FROM public.pi_jobs WHERE idempotency_key='q:lo'),'wB','boom') = 'queued'$$, 'service_role');
SELECT pgtest.q('K11b the failed job is unlocked, keeps its error and is delayed by back-off (>5s)', $$(SELECT status='queued' AND locked_by IS NULL AND last_error='boom' AND run_after > now() + interval '5 seconds' FROM public.pi_jobs WHERE idempotency_key='q:lo')$$, 'service_role');
SELECT pgtest.t('K12 (make the retry due)', $$UPDATE public.pi_jobs SET run_after = now() - interval '1 second' WHERE idempotency_key='q:lo'$$, 'service_role');
SELECT pgtest.q('K13 retry is claimed again as attempt 2', $$(SELECT attempts FROM public.pi_claim_jobs('wC',5,interval '5 minutes',ARRAY['provider_healthcheck']) WHERE idempotency_key='q:lo') = 2$$, 'service_role');
SELECT pgtest.q('K14a failing the FINAL attempt returns "dead"', $$public.pi_fail_job((SELECT id FROM public.pi_jobs WHERE idempotency_key='q:lo'),'wC','boom again') = 'dead'$$, 'service_role');
SELECT pgtest.q('K14b the dead-lettered job is finished and unlocked', $$(SELECT status='dead' AND finished_at IS NOT NULL AND locked_by IS NULL FROM public.pi_jobs WHERE idempotency_key='q:lo')$$, 'service_role');
SELECT pgtest.t('K15 setup: crashed worker (job running, lease about to expire)', $$INSERT INTO public.pi_jobs (job_type, idempotency_key, max_attempts) VALUES ('purge_retention','crash:1',3), ('purge_retention','crash:last',1)$$, 'service_role');
SELECT pgtest.q('K16 workers claim both', $$(SELECT count(*)=2 FROM public.pi_claim_jobs('wCrash',5,interval '5 minutes',ARRAY['purge_retention']))$$, 'service_role');
SELECT pgtest.t('K17 (simulate crash: leases expire)', $$UPDATE public.pi_jobs SET locked_at = now() - interval '2 minutes', lease_expires_at = now() - interval '1 minute' WHERE locked_by='wCrash'$$, 'service_role');
SELECT pgtest.q('K18 expired lease with attempts left is reclaimed by another worker', $$(SELECT attempts FROM public.pi_claim_jobs('wRescue',5,interval '5 minutes',ARRAY['purge_retention']) WHERE idempotency_key='crash:1') = 2$$, 'service_role');
SELECT pgtest.q('K19 expired lease on the final attempt dead-letters instead of retrying forever', $$(SELECT status='dead' FROM public.pi_jobs WHERE idempotency_key='crash:last')$$, 'service_role');
SELECT pgtest.t('K20 a running job must record its lock (constraint)', $$UPDATE public.pi_jobs SET status='running', locked_by=NULL WHERE idempotency_key='q:future'$$, 'service_role', NULL, '23514');
SELECT pgtest.q('K21 ordinary users cannot read the job queue', $$(SELECT count(*)=0 FROM public.pi_jobs)$$, 'authenticated', pgtest.u(2));

-- ===================================================================== L. row-level security (who can read / write)
SELECT pgtest.t('L2 anon cannot read cases', $$SELECT count(*) FROM public.pi_moderation_cases$$, 'anon', NULL, '42501');
SELECT pgtest.q('L3 ordinary user sees ZERO moderation cases even though rows exist', $$(SELECT count(*)=0 FROM public.pi_moderation_cases)$$, 'authenticated', pgtest.u(2));
SELECT pgtest.q('L4 ordinary user sees ZERO feature flags / policies / analyses / actions', $$(SELECT (SELECT count(*) FROM public.pi_feature_flags)+(SELECT count(*) FROM public.pi_policies)+(SELECT count(*) FROM public.pi_content_analyses)+(SELECT count(*) FROM public.pi_moderation_actions)+(SELECT count(*) FROM public.pi_audit_log) = 0)$$, 'authenticated', pgtest.u(2));
SELECT pgtest.q('L5 the BMN owner CAN read cases, policies, actions and the audit log', $$(SELECT (SELECT count(*) FROM public.pi_moderation_cases)>0 AND (SELECT count(*) FROM public.pi_policies)=10 AND (SELECT count(*) FROM public.pi_moderation_actions)>0 AND (SELECT count(*) FROM public.pi_audit_log)>0)$$, 'authenticated', pgtest.u(1));
SELECT pgtest.t('L6 even the owner cannot write directly through the client role', $$UPDATE public.pi_policies SET enabled=false$$, 'authenticated', pgtest.u(1), '42501');
SELECT pgtest.t('L7 ordinary user cannot write', format($$INSERT INTO public.pi_moderation_cases (subject_type, subject_id, source) VALUES ('post',%L,'user_report')$$, pgtest.u(999)), 'authenticated', pgtest.u(2), '42501');
SELECT pgtest.t('L8 ordinary user cannot flip a feature flag', $$UPDATE public.pi_feature_flags SET enabled=true$$, 'authenticated', pgtest.u(2), '42501');
SELECT pgtest.t('L9 anon cannot call the user functions', $$SELECT * FROM public.pi_my_moderation_notices()$$, 'anon', NULL, '42501');

-- ===================================================================== M. compatibility with existing account deletion
-- user3 (u(4)) gets rows in many pi_ tables, then deletes their account with the REAL baseline function.
SELECT pgtest.t('M1 setup: pi_ rows referencing user3', format($$
  INSERT INTO public.pi_moderation_cases (id, subject_type, subject_id, subject_user_id, source) VALUES (%1$L,'account',%2$L,%2$L,'automated');
  INSERT INTO public.pi_content_analyses (case_id, subject_type, subject_id, subject_user_id, analysis_kind, content_hash, provider, outcome, risk_score) VALUES (%1$L,'post',%3$L,%2$L,'text',repeat('e',64),'bmn_rules','clear',0.05);
  INSERT INTO public.pi_moderation_actions (id, case_id, target_user_id, subject_type, subject_id, action_type, actor_type, actor_id, mode, user_visible_reason) VALUES (%4$L,%1$L,%2$L,'account',%2$L,'warn','owner',%5$L,'enforced','Test warning');
  INSERT INTO public.pi_appeals (action_id, user_id, statement) VALUES (%4$L,%2$L,'I disagree with this warning, please review.');
  INSERT INTO public.pi_account_risk_assessments (user_id, risk_score, risk_level, explanation, model_version) VALUES (%2$L,0.1,'low','ok','rules-1');
  INSERT INTO public.pi_security_events (user_id, event_type, severity, source) VALUES (%2$L,'suspicious_login','medium','login_monitor');
  INSERT INTO public.pi_protective_restrictions (user_id, restriction_type, reason_code, actor_type, expires_at) VALUES (%2$L,'limit_posting','test','system', now()+interval '1 day');
  INSERT INTO public.pi_verification_evaluations (verification_request_id, user_id, criteria_version, checks, outcome) VALUES (%6$L,%2$L,1,'[{"check":"a","result":"fail"}]','insufficient_evidence');
  INSERT INTO public.pi_verification_decisions (user_id, evaluation_id, decision, decided_by_type, reason) SELECT %2$L, id, 'referred_to_human', 'system', 'needs a human' FROM public.pi_verification_evaluations WHERE verification_request_id = %6$L;
  SELECT public.pi_write_audit(%2$L,'user','test_event','account',%2$L::text,NULL,NULL,'before deletion');
$$, pgtest.u(601), pgtest.u(4), pgtest.u(602), pgtest.u(603), pgtest.u(1), pgtest.u(604)), 'service_role');
SELECT pgtest.q('M2 snapshot: existing BMN data for user3 is present', format($$(SELECT count(*)=1 FROM public.profiles WHERE id=%L) AND (SELECT count(*)=1 FROM public.posts WHERE user_id=%L)$$, pgtest.u(4), pgtest.u(4)));
SELECT pgtest.t('M3 user3 deletes their account using the REAL baseline bmn_delete_my_account()', $$SELECT public.bmn_delete_my_account()$$, 'authenticated', pgtest.u(4));
SELECT pgtest.q('M4 account is gone from auth.users, profiles and posts', format($$(SELECT count(*)=0 FROM auth.users WHERE id=%1$L) AND (SELECT count(*)=0 FROM public.profiles WHERE id=%1$L) AND (SELECT count(*)=0 FROM public.posts WHERE user_id=%1$L)$$, pgtest.u(4)));
SELECT pgtest.q('M5 personal pi_ rows were erased with the account (appeals, risk, events, restrictions, evaluations)', format($$(SELECT count(*)=0 FROM public.pi_appeals WHERE user_id=%1$L) AND (SELECT count(*)=0 FROM public.pi_account_risk_assessments WHERE user_id=%1$L) AND (SELECT count(*)=0 FROM public.pi_security_events WHERE user_id=%1$L) AND (SELECT count(*)=0 FROM public.pi_protective_restrictions WHERE user_id=%1$L) AND (SELECT count(*)=0 FROM public.pi_verification_evaluations WHERE user_id=%1$L)$$, pgtest.u(4)));
SELECT pgtest.q('M6 moderation history survives, anonymised (target set to NULL)', format($$(SELECT count(*)=1 AND bool_and(target_user_id IS NULL) FROM public.pi_moderation_actions WHERE id=%L) AND (SELECT count(*)=1 AND bool_and(subject_user_id IS NULL) FROM public.pi_moderation_cases WHERE id=%L)$$, pgtest.u(603), pgtest.u(601)));
SELECT pgtest.q('M7 the audit log entry survives the deletion', $$(SELECT count(*)=1 FROM public.pi_audit_log WHERE action='test_event')$$);
SELECT pgtest.q('M8 other users'' data was not affected by the deletion', format($$(SELECT count(*)=1 FROM public.profiles WHERE id=%L) AND (SELECT count(*)=1 FROM public.posts WHERE user_id=%L)$$, pgtest.u(2), pgtest.u(2)));
